// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        uint256 oldBetLimit = c.currentBetLimit();
        c.AdjustBetAmounts(amount);
        uint256 newBetLimit = c.currentBetLimit();
        // The reference C sets betLimit = amount, so newBetLimit == amount.
        // The mutant sets betLimit = amount + 1, so newBetLimit == amount + 1.
        // General rule: newBetLimit == amount means the original is correct.
        assertTrue(newBetLimit == amount, "newBetLimit should be exactly the input amount");
    }
}

